// Priority list for ambiguous dials shared by many countries (e.g. "+1" / "+7").
// When looking up by dial alone, prefer these instead of the first alphabetical match.
const DIAL_PRIORITY: Record<string, string> = {
  "1": "Estados Unidos",
  "7": "Rússia",
};

/** Find the country whose dial is the longest prefix of `input` (digits only, no +). */
export function findCountryByDial(input: string): Country | undefined {
  const digits = input.replace(/\D/g, "");
  if (!digits) return undefined;
  // Try longest prefixes first (up to 4 digits — NANP subcodes go to 4).
  for (let len = Math.min(4, digits.length); len >= 1; len--) {
    const prefix = digits.slice(0, len);
    const matches = COUNTRIES.filter((c) => c.dial === prefix);
    if (matches.length === 0) continue;
    const preferred = DIAL_PRIORITY[prefix];
    if (preferred) {
      const p = matches.find((c) => c.name === preferred);
      if (p) return p;
    }
    return matches[0];
  }
  return undefined;
}

/** Find by exact dial (no prefix logic). */
export function findCountryByExactDial(dial: string): Country | undefined {
  const d = dial.replace(/\D/g, "");
  const matches = COUNTRIES.filter((c) => c.dial === d);
  if (matches.length === 0) return undefined;
  const preferred = DIAL_PRIORITY[d];
  if (preferred) {
    const p = matches.find((c) => c.name === preferred);
    if (p) return p;
  }
  return matches[0];
}

/** Insert spaces into digit string according to the mask groups. Truncates at total. */
export function formatByMask(digits: string, mask: number[]): string {
  const clean = digits.replace(/\D/g, "");
  if (mask.length === 0) return clean;
  const total = mask.reduce((a, b) => a + b, 0);
  const trimmed = clean.slice(0, total);
  const out: string[] = [];
  let i = 0;
  for (const g of mask) {
    if (i >= trimmed.length) break;
    out.push(trimmed.slice(i, i + g));
    i += g;
  }
  return out.join(" ");
}

/** Formata um número completo (ex: +5511987654321) para exibição (ex: +55 11 98765-4321). */
export function formatDisplayPhone(fullPhone?: string | null): string {
  if (!fullPhone) return "";
  const digits = fullPhone.replace(/\D/g, "");
  if (!digits) return fullPhone;
  const country = [...COUNTRIES]
    .sort((a, b) => b.dial.length - a.dial.length)
    .find((c) => digits.startsWith(c.dial));
  if (!country) return `+${digits}`;
  const local = digits.slice(country.dial.length);
  // Ajustes de máscara/ separadores para formatos de exibição mais naturais.
  const displayMasks: Record<string, number[]> = {
    "44": [2, 4, 4], // Reino Unido: 20 7946 1234
  };
  const mask = displayMasks[country.dial] ?? country.mask;
  let localFormatted = formatByMask(local, mask);
  // Para países com formato "grupo fixo + número" (Brasil, EUA, etc.), usa hífen no último grupo.
  if (mask.length >= 2 && localFormatted.includes(" ")) {
    const lastSpace = localFormatted.lastIndexOf(" ");
    localFormatted = localFormatted.slice(0, lastSpace) + "-" + localFormatted.slice(lastSpace + 1);
  }
  return `+${country.dial} ${localFormatted}`;
}

/** Example placeholder for a country ("12 99209 1037" style). */
export function placeholderFor(c: Country | undefined): string {
  if (!c) return "";
  return c.mask.map((n) => "0".repeat(n)).join(" ");
}
